import pandas as pd

def inspect_excel(file_path):
    print(f"--- Inspecting {file_path} ---")
    try:
        # Try reading with default engine, usually openpyxl for xlsx and xlrd for xls
        if file_path.endswith('.xls'):
            df = pd.read_excel(file_path, engine='xlrd', header=None, nrows=20)
        else:
            df = pd.read_excel(file_path, header=None, nrows=20)
        print(df)
    except Exception as e:
        print(f"Error reading {file_path}: {e}")
    print("\n")

inspect_excel('ERP-2025-table10.xls')
inspect_excel('ERP-2025-table12.xls')
inspect_excel('CPI.xlsx')

import pandas as pd

def check_cols(file_path):
    print(f"--- Checking Columns for {file_path} ---")
    try:
        if file_path.endswith('.xls'):
            df = pd.read_excel(file_path, engine='xlrd', header=None, nrows=10)
        else:
            df = pd.read_excel(file_path, header=None, nrows=10)

        # Print first 10 rows, first 5 columns
        print(df.iloc[:, 0:5])

    except Exception as e:
        print(f"Error: {e}")

check_cols('ERP-2025-table10.xls')
check_cols('ERP-2025-table12.xls')

import pandas as pd

def inspect_row(file_path, row_idx):
    print(f"--- Inspecting Row {row_idx} of {file_path} ---")
    try:
        if file_path.endswith('.xls'):
            df = pd.read_excel(file_path, engine='xlrd', header=None, nrows=20)
        else:
            df = pd.read_excel(file_path, header=None, nrows=20)

        row_data = df.iloc[row_idx]
        for i, val in enumerate(row_data):
            print(f"Col {i}: {val}")

    except Exception as e:
        print(f"Error: {e}")

inspect_row('ERP-2025-table10.xls', 5) # 1973
inspect_row('ERP-2025-table12.xls', 6) # 1973
